function maxValue(n, index, maxSum) {
  const sideSum = (peak, count) => {
    if (peak > count) {
      return (2 * peak - count - 1) * count / 2;
    }
    return (peak - 1) * peak / 2 + (count - peak + 1);
  };

  let low = 1;
  let high = maxSum - n + 1;
  while (low < high) {
    const mid = Math.ceil((low + high) / 2);
    const total = mid + sideSum(mid, index) + sideSum(mid, n - 1 - index);
    if (total <= maxSum) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

