function maxValue(n, index, maxSum) {
  // Cheapest array with a given peak: fall by 1 per step away from index, never below 1.
  const cost = (value) => {
    let sum = 0;
    for (let i = 0; i < n; i++) sum += Math.max(value - Math.abs(i - index), 1);
    return sum;
  };
  let value = 1;
  while (cost(value + 1) <= maxSum) value++;
  return value;
}

