function generate(rand, size) {
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 8);
    const index = Math.floor(rand() * n);
    const maxSum = n + Math.floor(rand() * 40);
    return [n, index, maxSum];
  }
  const LIMIT = 1e9;
  const shape = rand();
  let n;
  if (shape < 0.3) n = 1 + Math.floor(rand() * 1000);
  else if (shape < 0.6) n = 1 + Math.floor(rand() * 100000);
  else n = 1 + Math.floor(rand() * LIMIT);
  const index = Math.floor(rand() * n);
  const maxSum = n + Math.floor(rand() * (LIMIT - n + 1));
  return [n, index, maxSum];
}
